const name = 'Alice';
const age = 25;

// Old ES5 way
const oldStr = "My name is " + name + "\nAnd I am " + age + " years old.";

// Modern ES6 Template Literal
const modernStr = `My name is ${name}
And I am ${age} years old.`;

// Tagged Template (Advanced)
function highlight(strings, ...values) {
  console.log(strings); // Array of string chunks
  console.log(values);  // Array of evaluated expressions
}
